ON CONFLICT (district_number) DO UPDATE
  SET district_name = EXCLUDED.district_name, geom = EXCLUDED.geom, updated_at = now();

CREATE INDEX IF NOT EXISTS idx_council_districts_geom ON council_districts USING GIST (geom);

-- ---------------------------------------------------------------------------
-- council_district column + one-time backfill (in_ae already exists and was already backfilled
-- via a separate CSV import -- not touched here)
-- ---------------------------------------------------------------------------

ALTER TABLE tcad_properties ADD COLUMN IF NOT EXISTS council_district integer;

UPDATE tcad_properties p
SET council_district = (
  SELECT d.district_number FROM council_districts d
  WHERE ST_Contains(d.geom, ST_SetSRID(ST_MakePoint(p.centroid_lon, p.centroid_lat), 4326))
  LIMIT 1
)
WHERE p.centroid_lat IS NOT NULL AND p.centroid_lon IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_tcad_properties_council_district ON tcad_properties (council_district);

-- ---------------------------------------------------------------------------
-- Trigger: keep in_ae and council_district correct automatically going forward, for any insert
-- or centroid update, regardless of how the row gets there (bulk reload, manual edit, etc.)
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION set_derived_geo_fields()
RETURNS trigger AS $$
BEGIN
  IF NEW.centroid_lat IS NOT NULL AND NEW.centroid_lon IS NOT NULL THEN
    NEW.in_ae := EXISTS (
      SELECT 1 FROM ae_service_area a
      WHERE ST_Contains(a.geom, ST_SetSRID(ST_MakePoint(NEW.centroid_lon, NEW.centroid_lat), 4326))
    );
    NEW.council_district := (
      SELECT d.district_number FROM council_districts d
      WHERE ST_Contains(d.geom, ST_SetSRID(ST_MakePoint(NEW.centroid_lon, NEW.centroid_lat), 4326))
      LIMIT 1
    );
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_set_derived_geo_fields ON tcad_properties;
CREATE TRIGGER trg_set_derived_geo_fields
  BEFORE INSERT OR UPDATE OF centroid_lat, centroid_lon ON tcad_properties
  FOR EACH ROW
  EXECUTE FUNCTION set_derived_geo_fields();
